const axios = require('axios');
const fs = require('fs');
const crypto = require('crypto');

// Configuration
const API_URL = 'https://example.com/api/users';
const API_KEY = 'your_api_key';
const OUTPUT_FILE = 'user_data.json';
const ENCRYPTION_KEY = 'your_encryption_key'; // 32 bytes for AES-256

// Function to encrypt data
function encryptData(data, key) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), iv);
    let encrypted = cipher.update(data, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return { iv: iv.toString('hex'), encryptedData: encrypted };
}

// Function to download and encrypt user data
async function downloadAndEncryptUserData() {
